314	\begin{theorem}[Closeness of inner products]\label{prop:closeness-of-ip}
315		\lean{MIPStarRE.LDT.Preliminaries.closenessOfIP, MIPStarRE.LDT.Preliminaries.closenessOfIPAdjoint}
316		\leanok
317		\uses{def:approx_delta}
318		Let $\{A^x_a\}$, $\{B^x_a\}$, and $\{C^x_{a,b}\}$ be matrices. Suppose that $A^x_a \approx_\gamma B^x_a$ and that for all~$x$,
319		\[
320			\sum_a \Big(\sum_b C^x_{a,b}\Big) \Big(\sum_b C^x_{a,b}\Big)^\dagger \le I.
321		\]
322		Then
323		\begin{equation}
324			\E_{\bx} \sum_{a,b} \bra{\psi} C^{\bx}_{a,b} A^{\bx}_a  \ket{\psi} \approx_{\sqrt{\gamma}} \E_{\bx} \sum_{a,b} \bra{\psi} C^{\bx}_{a,b} B^{\bx}_a  \ket{\psi}. \label{eq:closeness3}
325		\end{equation}
326		Similarly, suppose that $(A^x_a)^\dagger \approx_\gamma (B^x_a)^\dagger$ and that for all~$x$,
327		\[
328			\sum_a \Big(\sum_b C^x_{a,b}\Big)^\dagger \Big(\sum_b C^x_{a,b}\Big) \le I.
329		\]
330		Then
331		\begin{equation}
332			\E_{\bx} \sum_{a,b} \bra{\psi} A^{\bx}_a  C^{\bx}_{a,b} \ket{\psi} \approx_{\sqrt{\gamma}} \E_{\bx} \sum_{a,b} \bra{\psi} B^{\bx}_a  C^{\bx}_{a,b}  \ket{\psi}. \label{eq:closeness4}
333		\end{equation}
334	\end{theorem}
335	\begin{proof}
336		\leanok
337		To prove \eqref{eq:closeness3}, write the difference as
338		\[
339			\E_{\bx} \sum_a \bra{\psi} \Big(\sum_b C^\bx_{a,b}\Big) (A^\bx_a-B^\bx_a) \ket{\psi}.
340		\]
341		Cauchy--Schwarz bounds its magnitude by
342		\[
343			\Big( \E_{\bx} \sum_a \bra{\psi} \Big(\sum_b C^{\bx}_{a,b}\Big)\Big(\sum_b C^{\bx}_{a,b}\Big)^\dagger \ket{\psi} \Big)^{1/2}
344			\Big( \E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a - B^{\bx}_a)^\dagger (A^{\bx}_a - B^{\bx}_a) \ket{\psi} \Big)^{1/2},
345		\]
346		and the two hypotheses bound these factors by $1$ and $\sqrt{\gamma}$ respectively. For \eqref{eq:closeness4}, rewrite the difference as
347		\[
348			\E_{\bx} \sum_{a,b} \bra{\psi} (C^{\bx}_{a,b})^\dagger \big((A^{\bx}_a)^\dagger-(B^{\bx}_a)^\dagger\big) \ket{\psi},
349		\]
350		and apply \eqref{eq:closeness3} to the adjoint families.
351	\end{proof}
